// ═══════════════════════════════════════════════════════════════════════
//  THE ONLY NODE YOU EDIT. One { … } block per sender domain you care about.
// ═══════════════════════════════════════════════════════════════════════
//
//  domain    REQUIRED. Sender domain, e.g. 'tdv.org'. Subdomains count
//            (burs@mail.tdv.org); lookalikes do not (info@nottdv.org) —
//            Igor re-checks the From header properly, because Gmail's own
//            from: operator is a fuzzy token match and lets those through.
//
//  agent     Optional, default 'speda'. Who reads the mail and writes the
//            push — 'sentinel' for bank/money, 'ultron' for university,
//            'centurion' for security notices.
//
//  intent    Optional. What the agent should DO with it. The mail body is
//            already in the payload either way, so the agent never re-fetches.
//            Leave empty for the sensible default (summarise + flag deadlines).
//
//  extra     Optional extra Gmail query terms, ANDed on: 'is:unread',
//            'has:attachment', 'subject:fatura'.
//
//  label     Optional, default 'SPEDA-Seen'. The Gmail label that marks a
//            message handled. Give a rule its OWN label only if two rules
//            could match the SAME message — otherwise whichever fires first
//            hides it from the other.
//
//  max       Optional, default 10, cap 25. Messages per scan.
//
const MAILS = [

  {
    domain: 'tdv.org',
    agent: 'speda',
    intent: '',
    extra: '',
  },

  // { domain: 'garantibbva.com.tr', agent: 'sentinel',
  //   intent: 'Bu bir banka bildirimi. Tutarı, işlem tipini ve tarihi çıkar; olağandışıysa açıkça uyar.' },

];

// ── Nothing below this line needs editing ───────────────────────────────
const DEFAULT_INTENT = "New mail arrived. The sender, subject and body of every message are ALREADY in `messages` in this payload — do NOT call Gmail or load a toolset, you have the mail. Read it and write the owner one short push in their language: who wrote, what they actually want, and any deadline, amount or action required. One line per message if several arrived. If something needs a reply or a date on the calendar, say so plainly and offer to do it — do not do it unasked.";

const out = [];
MAILS.forEach((m, i) => {
  if (!m || !m.domain) { return; }
  out.push({
    json: {
      domain: String(m.domain).trim().replace(/^@/, ''),
      agent: (m.agent || 'speda').trim(),
      intent: m.intent || DEFAULT_INTENT,
      extra_query: m.extra || '',
      label: m.label || 'SPEDA-Seen',
      max_results: m.max || 10,
    },
    pairedItem: { item: 0 },
  });
});
// An empty list returns no items, which stops the branch harmlessly.
return out;

const store = $getWorkflowStaticData('global');
const broken = store.broken || {};
const cfg = $('Mail list').all();
const out = [];

$input.all().forEach((item, i) => {
  const res = item.json || {};
  const conf = (cfg[i] && cfg[i].json) || {};
  const id = conf.domain || ('#' + i);
  const status = res.status || 'error';

  // Watch health, EDGE-triggered per domain: a revoked Google token makes
  // every rule blind at once, and at a 10-minute cadence that would be 144
  // identical pushes a day. One on the transition is enough.
  if (status !== 'ok') {
    if (!broken[id]) {
      broken[id] = true;
      out.push({ json: {
        alert: true, domain: id, agent: conf.agent || 'speda',
        detail: res.detail || res.message || status,
        count: 0, message_ids: [], messages: [], intent: '',
      }, pairedItem: { item: i } });
    }
    return;
  }
  broken[id] = false;

  // The normal path: nothing arrived. No items = branch stops = no turn.
  if (!res.count) { return; }

  out.push({ json: {
    alert: false,
    domain: id,
    agent: conf.agent || 'speda',
    intent: conf.intent || '',
    count: res.count,
    message_ids: res.message_ids || [],
    messages: res.messages || [],
    label: conf.label || 'SPEDA-Seen',
  }, pairedItem: { item: i } });
});

store.broken = broken;
return out;
